    def addBinary(self, a: str, b: str) -> str:
        # Write your solution here
        carry = 0
        res = []
        i, j = len(a) - 1, len(b) - 1
        while i >= 0 or j >= 0:
            temp = 0
            if i >= 0:
                temp += int(a[i])
                i -= 1
            if j >= 0:
                temp += int(b[j])
                j -= 1
            temp += carry
            temp, carry = temp % 2, temp // 2
            res.append(str(temp))
        if carry:
            res.append("1")
        return "".join(res[::-1])

