# Divide and conquer
class Solution:
    def longestCommonPrefix(self, strs: list[str]) -> str:
        if not strs:
            return ""
        return self._lcp(strs, 0, len(strs) - 1)

    def _lcp(self, strs, lo, hi):
        if lo == hi:
            return strs[lo]
        mid = (lo + hi) // 2
        left = self._lcp(strs, lo, mid)
        right = self._lcp(strs, mid + 1, hi)
        return self._common_prefix(left, right)

    def _common_prefix(self, a: str, b: str) -> str:
        i = 0
        m = min(len(a), len(b))
        while i < m and a[i] == b[i]:
            i += 1
        return a[:i]

