    def longestConsecutive(self, nums: list[int]) -> int:
        # Write your solution here
        if len(nums) == 0:
            return 0
        num_set = set(nums)
        max_len = 1
        for num in nums:
            if num-1 not in num_set: # check is num is the start of the chain
                start = num
                while start + 1 in num_set:
                    start += 1
                    max_len = max(max_len, start - num + 1)
        return max_len

