    def searchRange(self, nums: list[int], target: int) -> list[int]:
        # Write your solution here
        # [5, 7, 8, 8, 8, 8, 9]

        # binary search on left

        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                right = mid - 1      # move left to search for the begining of the target sequence
            elif nums[mid] < target: # this is for narrowing down the range
                left = mid + 1
            else:
                right = mid -1

        left, right = 0, len(nums) - 1  
        result2 = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result2 = mid
                left = mid + 1       # move right
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid -1

        return [result, result2]

