class Solution:
    def lruCache(self, operations: list[str], args: list[list[int]]) -> list:
        result = []
        cache = None
        for op, arg in zip(operations, args):
            if op == "LRUCache":
                cache = LRUCache(arg[0])
                result.append(None)
            elif op == "get":
                result.append(cache.get(arg[0]))
            elif op == "put":
                cache.put(arg[0], arg[1])
                result.append(None)
        return result

