import heapq
class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        # Write your solution here
        ctr = Counter(nums)
        heap = []
        for key, v in ctr.items():
            if len(heap) < k:
                heapq.heappush(heap, (v, key))
            else:
                heapq.heappushpop(heap, (v, key))
        return [x[1] for x in heap]
